import React, { useCallback, useEffect, useRef, useState } from 'react';

export type RailMarker =
  | { kind: 'dot'; className?: string; title?: string }
  | { kind: 'pulse'; title?: string }
  | { kind: 'badge'; text: string | number; title?: string };

export interface RailTabDef {
  id: string;
  label: string;
  hint?: string;
  icon?: React.ReactNode;
  /** Optional live marker at the row's right edge: status dot (dynamic
      colour), LIVE pulse (semantic emerald), or count badge (neutral
      wash inheriting the tab text so it reads on any active fill). */
  marker?: RailMarker;
}

interface SectionRailTabsProps {
  tabs: RailTabDef[];
  active: string;
  onChange: (id: string) => void;
  ariaLabel: string;
  // Layout direction. 'horizontal' (default) is a scrollable strip — one
  // tap on every breakpoint. 'vertical' is a stacked side nav for pages
  // with many sections (Theme Studio): full-width rows, indicator line on
  // the left edge growing top → bottom (rail variant) or compact chips
  // stacked on the left (chips variant — same outfit as phones, left).
  orientation?: 'horizontal' | 'vertical';
  // Visual density. 'rail' (default) shows icon + label + hint rows with a
  // growing indicator line. 'chips' is the compact style: small rounded
  // pills with icon + label only (no hint/notes text, no indicator line —
  // the active chip is the solid themed fill), edge-fade scrolling, and
  // the active chip auto-centered. Horizontal chips scroll left → right
  // on top (phones); vertical chips stack top → bottom on the left
  // (Theme Studio desktop).
  variant?: 'rail' | 'chips';
}

// SectionRailTabs — the shared tab style for Security + Database
// (horizontal strip) and Theme Studio (vertical side nav).
//
// Why a second style next to the System scope cards:
//   - System switches between exactly 2 scopes (machine vs app) with live
//     footnotes — big cards fit. Security (5 sections) and Database
//     (4 sections) switch between same-kind sections with short hints —
//     a compact horizontal rail fits, on desktop AND phones (horizontally
//     scrollable, one tap — no bottom-pill dropdown, no separate desktop
//     row / vertical side rail per page).
//   - Theme Studio has ~20 sections: same rail, vertical orientation —
//     stacked full-width rows with the indicator on the left edge.
//   - Active item keeps the themed solid pill fill plus an indicator line
//     that grows on select (bottom, left → right / left edge, top →
//     bottom); inactive items stay transparent with a hover wash. Item
//     colors reuse the Tabs-tab vars (--ks-tab-*); the indicator + icon
//     size have their own rail_* knobs in the same tab.
//     An optional live marker (status dot / LIVE pulse / count badge)
//     rides at the row's right edge — used by the instance overview for
//     status, streaming state and audit count.
export const SectionRailTabs: React.FC<SectionRailTabsProps> = ({
  tabs,
  active,
  onChange,
  ariaLabel,
  orientation = 'horizontal',
  variant = 'rail',
}) => {
  const vertical = orientation === 'vertical';
  // Chips work on both axes: horizontal chips scroll left → right on top
  // (phones), vertical chips stack top → bottom on the left (desktop).
  // Same outfit — compact icon + label pills, no hints, no indicator.
  const chips = variant === 'chips';
  const refs = useRef<Record<string, HTMLButtonElement | null>>({});

  const focusTab = useCallback((id: string) => {
    refs.current[id]?.focus();
  }, []);

  const onKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      const idx = Math.max(0, tabs.findIndex((t) => t.id === active));
      let next: string | null = null;
      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') next = tabs[(idx + 1) % tabs.length].id;
      else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') next = tabs[(idx + tabs.length - 1) % tabs.length].id;
      else if (e.key === 'Home') next = tabs[0].id;
      else if (e.key === 'End') next = tabs[tabs.length - 1].id;
      if (next) {
        e.preventDefault();
        onChange(next);
        focusTab(next);
      }
    },
    [tabs, active, onChange, focusTab],
  );

  const scrollRef = useRef<HTMLDivElement | null>(null);
  // Edge-fade flags for the chips scroller — mask only the edge(s) that
  // can actually scroll further, so fitted content never gets clipped.
  const [scrollEdges, setScrollEdges] = useState('');

  useEffect(() => {
    if (!chips) return;
    const el = scrollRef.current;
    if (!el) return;
    const update = () => {
      if (vertical) {
        const canT = el.scrollTop > 4;
        const canB = el.scrollTop + el.clientHeight < el.scrollHeight - 4;
        setScrollEdges(`${canT ? 'can-scroll-t' : ''} ${canB ? 'can-scroll-b' : ''}`);
      } else {
        const canL = el.scrollLeft > 4;
        const canR = el.scrollLeft + el.clientWidth < el.scrollWidth - 4;
        setScrollEdges(`${canL ? 'can-scroll-l' : ''} ${canR ? 'can-scroll-r' : ''}`);
      }
    };
    update();
    el.addEventListener('scroll', update, { passive: true });
    window.addEventListener('resize', update);
    return () => {
      el.removeEventListener('scroll', update);
      window.removeEventListener('resize', update);
    };
  }, [chips, vertical, tabs.length]);

  // Keep the active chip centered on its scroll axis (block:'nearest' /
  // inline:'nearest' never moves the page on the cross axis).
  useEffect(() => {
    if (!chips) return;
    refs.current[active]?.scrollIntoView({
      behavior: 'smooth',
      block: vertical ? 'center' : 'nearest',
      inline: vertical ? 'nearest' : 'center',
    });
  }, [chips, vertical, active]);

  return (
    <section
      aria-label={`${ariaLabel} navigation`}
      className={
        chips
          ? vertical
            ? 'ks-card rounded-2xl p-1.5'
            : 'ks-card rounded-full p-1'
          : 'ks-card rounded-xl p-1.5 sm:p-2'
      }
    >
      <div
        ref={scrollRef}
        role="tablist"
        aria-label={ariaLabel}
        aria-orientation={orientation}
        onKeyDown={onKeyDown}
        className={
          vertical
            ? chips
              ? `ks-chipscroll ks-chipscroll-vertical scroll-smooth flex flex-col items-stretch gap-1.5 overflow-y-auto px-0.5 py-0.5 max-h-[70vh] ${scrollEdges}`
              : 'flex flex-col items-stretch gap-1 max-h-[70vh] overflow-y-auto pr-0.5'
            : chips
              ? `ks-chipscroll scroll-smooth flex items-stretch gap-1.5 overflow-x-auto px-1 py-0.5 ${scrollEdges}`
              : 'ks-hscroll flex items-stretch gap-1 overflow-x-auto pb-0.5'
        }
      >
        {tabs.map((t) => {
          const isActive = active === t.id;
          return (
            <button
              key={t.id}
              ref={(el) => {
                refs.current[t.id] = el;
              }}
              type="button"
              role="tab"
              id={`rail-tab-${t.id}`}
              aria-selected={isActive}
              aria-controls={`rail-panel-${t.id}`}
              tabIndex={isActive ? 0 : -1}
              onClick={() => onChange(t.id)}
              data-active={isActive}
              data-orientation={orientation}
              className={`ks-rail-tab ks-rail-anim group flex items-center min-w-0 outline-none focus-visible:ring-2 focus-visible:ring-white/60 focus-visible:ring-offset-2 focus-visible:ring-offset-black ${
                chips
                  ? vertical
                    ? 'ks-chip w-full gap-1.5 px-3 py-1.5 text-left'
                    : 'ks-chip shrink-0 gap-1.5 px-3 py-1.5 whitespace-nowrap'
                  : `${vertical ? 'w-full' : 'shrink-0'} gap-2.5 px-3 py-2 text-left`
              } ${isActive ? 'is-active' : ''}`}
            >
              {t.icon && (
                <span aria-hidden="true" className="ks-rail-ico">
                  {t.icon}
                </span>
              )}
              <span className="flex flex-col min-w-0">
                <span
                  className={
                    chips
                      ? 'text-[13px] font-medium leading-none whitespace-nowrap'
                      : 'text-sm font-medium leading-tight whitespace-nowrap'
                  }
                >
                  {t.label}
                </span>
                {t.hint && !chips && (
                  <span className={`ks-rail-hint ${vertical ? '' : 'hidden sm:block'}`} title={t.hint}>
                    {t.hint}
                  </span>
                )}
              </span>
              {t.marker?.kind === 'dot' && (
                <span
                  aria-hidden="true"
                  title={t.marker.title}
                  className={`ml-0.5 shrink-0 w-2 h-2 rounded-full ${t.marker.className ?? 'bg-gray-500'}`}
                />
              )}
              {t.marker?.kind === 'pulse' && (
                <span
                  aria-hidden="true"
                  title={t.marker.title ?? 'Live'}
                  className="ml-0.5 shrink-0 relative flex w-2 h-2"
                >
                  <span className="absolute inline-flex w-full h-full rounded-full bg-emerald-400 opacity-60 animate-ping" />
                  <span className="relative inline-flex rounded-full w-2 h-2 bg-emerald-400" />
                </span>
              )}
              {t.marker?.kind === 'badge' && (
                <span
                  title={t.marker.title}
                  className="ml-0.5 shrink-0 min-w-[20px] text-center text-[10px] font-semibold tabular-nums px-1.5 py-0.5 rounded-full bg-black/10"
                >
                  {t.marker.text}
                </span>
              )}
              {/* Indicator — horizontal: bottom line growing left → right;
                  vertical: left-edge line growing top → bottom (see
                  .ks-rail-tab[data-orientation='vertical'] in index.css). */}
              <span aria-hidden="true" className="ks-rail-bar" data-active={isActive} />
            </button>
          );
        })}
      </div>
    </section>
  );
};

export default SectionRailTabs;
