// ---- Stack create-form draft -----------------------------------------------
// Structured manifest builder (mirrors ModStudio's draft contract): the
// create form edits structured tabs and installs through POST /api/stacks/
// (X-KS-Source: studio) so the backend validates capabilities + seeds
// pending grants like any upload.

export interface StackStudioDraft {
  name: string;
  slug: string;
  version: string;
  description: string;
  icon: string;
  color: string;
  category: string;
  runtime: string;
  entrypoint: string;
  themeMode: StackThemeMode;
  pageStyle: StackPageStyle;
  permissionsRequested: StackPermissionRequest[];
  // Panel permission keys requested for the stack (same vocabulary as the
  // API key / role forms: MANAGE_USERS, STACKS_VIEW, ...). Surfaced through
  // the Permission tab's RolePermissions section so the stack form matches
  // the API key form. Emitted into the manifest as `panelPermissions`;
  // the backend keeps it as raw-manifest pass-through (forward-compatible).
  panelPermissions: string[];
  // Install section: where the stack runs + how it gets installed.
  // `installType` picks the backend target (docker container vs host
  // process); `installImage` is the docker image when type is docker.
  // `installSteps` is the installation workflow (same step shape as the
  // template install workflow so the UI can share TemplateInstallSection).
  installType: StackInstallType;
  installImage: string;
  installSteps: StackInstallStep[];
  installTimeoutS: string;
  // Launch section: workflow steps that run every time the stack launches
  // (same step shape as the install workflow so the UI shares
  // TemplateInstallSection; only the run moment differs).
  launchSteps: StackInstallStep[];
  launchTimeoutS: string;
  // Ask-at-launch tokens: values prompted for at launch time and exported
  // as environment variables (token NAME is the ENV key, e.g. API_TOKEN
  // becomes $API_TOKEN). Mirrors the template env-var "ask" behaviour.
  launchTokens: StackLaunchToken[];
  // Location type (General tab): 'host' = stack on this same host,
  // 'outside' = stack elsewhere. Outside/WSS uses node-form style
  // remoteHost + remotePort (bare host, no scheme); Outside/POST uses a
  // full remoteUrl. remoteSecret is an optional shared secret for either.
  locationType: StackLocationType;
  remoteHost: string;
  remotePort: string;
  remoteUrl: string;
  remoteProtocol: StackRemoteProtocol;
  remoteSecret: string;
  backendScript: string;
  frontendHtml: string;
  frontendCss: string;
  simplePage: string;
  spec: Record<string, any>;
}

// Install target — mirrors the template driver choice reduced to the two
// stack targets: a Docker container, or a Host process (static/nodejs/python
// sidecar via runtime+entrypoint).
export type StackInstallType = 'docker' | 'host';

export const STACK_INSTALL_TYPES: Array<{ value: StackInstallType; label: string; hint: string }> = [
  { value: 'docker', label: 'Docker', hint: 'Run in a container from an image' },
  { value: 'host', label: 'Host', hint: 'Run on the host via runtime + entrypoint' },
];

// One installation workflow step. Field-for-field compatible with the
// template InstallStep so StackForm can reuse TemplateInstallSection
// without conversion.
export type StackInstallAction =
  | 'shell'
  | 'download'
  | 'extract'
  | 'move'
  | 'write'
  | 'chmod'
  | 'mkdir'
  | 'git_clone'
  | 'pip_install'
  | 'npm_install'
  | 'http_check';

export interface StackInstallStep {
  action: StackInstallAction;
  command: string;
  url: string;
  filename: string;
  archive: string;
  dest: string;
  from: string;
  to: string;
  path: string;
  content: string;
  branch: string;
  retries: string;
  ignore_errors: boolean;
}

export const blankStackInstallStep = (): StackInstallStep => ({
  action: 'shell',
  command: '',
  url: '',
  filename: '',
  archive: '',
  dest: '',
  from: '',
  to: '',
  path: '',
  content: '',
  branch: 'main',
  retries: '0',
  ignore_errors: false,
});

// One ask-at-launch token. The launcher prompts for a value (unless a
// default covers it and the token isn't required) and exports the answer
// as the environment variable NAME — usable in workflow steps as
// {{NAME}} / ${NAME} / $(NAME), exactly like template env vars.
export interface StackLaunchToken {
  name: string;
  label: string;
  description: string;
  default: string;
  required: boolean;
  secret: boolean;
}

export const blankStackLaunchToken = (): StackLaunchToken => ({
  name: '',
  label: '',
  description: '',
  default: '',
  required: false,
  secret: true,
});

