  color: '',
  category: 'dashboard',
  runtime: 'static',
  entrypoint: '',
  themeMode: 'panel',
  pageStyle: 'spa',
  permissionsRequested: [],
  panelPermissions: [],
  installType: 'docker',
  installImage: '',
  installSteps: [],
  installTimeoutS: '',
  launchSteps: [],
  launchTimeoutS: '',
  launchTokens: [],
  locationType: 'host',
  remoteHost: '',
  remotePort: '',
  remoteUrl: '',
  remoteProtocol: 'wss',
  remoteSecret: '',
  backendScript: '',
  frontendHtml: '',
  frontendCss: '',
