import client from '@/shared/api/client';
import type {
  Stack,
  StackActivateConflict,
  StackFileContent,
  StackFileEntry,
  StackNavEntry,
  StackEngineStatus,
  StackPageEntry,
  StackPageContent,
} from '@/shared/types/stack';

// Admin Stacks API — /api/stacks collection (MANAGE_STACKS-gated) plus the
// content endpoints under /api/stacks/v1/* (STACKS_VIEW-gated). Session rides
// the HttpOnly cookie; no extra headers.

export function extractStackApiError(e: any, fallback: string): string {
  const data = e?.response?.data;
  if (typeof data === 'string' && data.trim()) return data;
  if (data && typeof data === 'object') {
    const msg = data.error ?? data.message ?? data.detail;
    if (typeof msg === 'string' && msg.trim()) return msg;
    try {
      const json = JSON.stringify(data);
      if (json && json !== '{}') return json;
    } catch {
      /* fall through */
    }
  }
  if (typeof e?.message === 'string' && e.message.trim()) return e.message;
  return fallback;
}

export interface StackGrantDecision {
  capability: string;
  granted: boolean;
}

export async function listStacks(): Promise<Stack[]> {
  const res = await client.get<Stack[]>('/api/stacks/');
  return res.data;
}

export async function getStack(id: number): Promise<Stack> {
  const res = await client.get<Stack>(`/api/stacks/${id}`);
  return res.data;
}

export async function createStackFromManifest(
  manifest: Record<string, any>,
  source: 'studio' | 'json' = 'json',
): Promise<Stack> {
  const res = await client.post<Stack>('/api/stacks/', manifest, {
    headers: { 'Content-Type': 'application/json', 'X-KS-Source': source },
  });
  return res.data;
}

export async function uploadStackPackage(packageFile: File): Promise<Stack> {
  const form = new FormData();
  form.append('package', packageFile);
  const res = await client.post<Stack>('/api/stacks/', form, {
    headers: { 'Content-Type': 'multipart/form-data' },
    responseType: 'json',
  });
  return res.data;
}

export async function installStackFromUrl(url: string): Promise<Stack> {
  const res = await client.post<Stack>(
    '/api/stacks/url',
    { url },
    { headers: { 'Content-Type': 'application/json' } },
  );
  return res.data;
}

export async function downloadStack(id: number): Promise<Blob> {
  const res = await client.get<Blob>(`/api/stacks/${id}/download`, {
    responseType: 'blob',
  });
  return res.data;
}

export async function updateStack(
  id: number,
  payload: { name: string; category: string; version: string; description: string; icon: string; color?: string; spec?: unknown; proxyPort?: number; proxyRootUrl?: string },
): Promise<Stack> {
  const res = await client.put<Stack>(`/api/stacks/${id}`, payload);
  return res.data;
}

// stackAppUrl returns the panel-served URL of a stack's proxied Go app
// (/<root>/), or '' when the proxy is off. Plain anchor href (outside the
// Router) since the mount lives outside the SPA route tree.
export function stackAppUrl(s: Pick<Stack, 'proxy_port' | 'proxy_root_url' | 'active'>): string {
  if (!s.active || !s.proxy_port || !s.proxy_root_url) return '';
  return `/${s.proxy_root_url}/`;
}

export async function deleteStack(id: number, wipe = false): Promise<void> {
  await client.delete(`/api/stacks/${id}${wipe ? '?wipe=1' : ''}`);
}

export async function setStackGrants(id: number, grants: StackGrantDecision[]): Promise<void> {
  await client.put(`/api/stacks/${id}/grants`, { grants });
}

// Activate resolves void on success, or the 409 checklist for the grant modal.
export async function activateStack(id: number): Promise<void | StackActivateConflict> {
  try {
    await client.post(`/api/stacks/${id}/activate`);
    return;
  } catch (e: any) {
    if (e?.response?.status === 409) {
      return e.response.data as StackActivateConflict;
    }
    throw e;
  }
}

export async function deactivateStack(id: number): Promise<void> {
  await client.post(`/api/stacks/${id}/deactivate`);
}

// ---- Async operation console ------------------------------------------------
// Install / launch / reinstall run as server-side jobs with step progress +
// live logs. Closing the console only dismisses the view (the job keeps
// running); Stop cancels it. Poll getStackOp while status is "running".

export type StackOpName = 'install' | 'launch' | 'reinstall';
export type StackOpStatus = 'running' | 'done' | 'error' | 'cancelled';
export type StackOpStepState = 'pending' | 'running' | 'done' | 'error' | 'skipped';

export interface StackOpStep {
  name: string;
  state: StackOpStepState;
  detail?: string;
}

export interface StackOpJob {
  job_id: string;
  stack_id: number;
  op: StackOpName;
  status: StackOpStatus;
  steps: StackOpStep[];
  logs: string[];
  error?: string;
  created_at: string;
  updated_at: string;
}

export async function startStackOp(id: number, op: StackOpName): Promise<StackOpJob> {
  const res = await client.post<StackOpJob>(`/api/stacks/${id}/op/${op}`);
  return res.data;
}

export async function getStackOp(id: number, jobId: string): Promise<StackOpJob> {
  const res = await client.get<StackOpJob>(`/api/stacks/${id}/op/${encodeURIComponent(jobId)}`);
  return res.data;
}

export async function stopStackOp(id: number, jobId: string): Promise<StackOpJob> {
  const res = await client.post<StackOpJob>(`/api/stacks/${id}/op/${encodeURIComponent(jobId)}/stop`);
  return res.data;
}

export async function getStackNav(): Promise<StackNavEntry[]> {
  const res = await client.get<StackNavEntry[]>('/api/stacks/nav');
  return res.data;
}

export async function getStackEngine(): Promise<StackEngineStatus> {
  const res = await client.get<StackEngineStatus>('/api/stacks/engine');
  return res.data;
}

export async function setStackEngine(enabled: boolean): Promise<{ enabled: boolean }> {
  const res = await client.put('/api/stacks/engine', { enabled });
  return res.data;
}

// Content endpoints (served from the extracted workdir, active stacks only).
export async function listStackPages(slug: string): Promise<StackPageEntry[]> {
  const res = await client.get<StackPageEntry[]>(`/api/stacks/v1/pages/${encodeURIComponent(slug)}`);
  return res.data;
}

export async function getStackPage(slug: string, page: string): Promise<StackPageContent> {
  const res = await client.get<StackPageContent>(
    `/api/stacks/v1/pages/${encodeURIComponent(slug)}/${encodeURIComponent(page)}`,
  );
  return res.data;
}

export function stackUiUrl(slug: string, subPath = ''): string {
  const base = `/api/stacks/v1/ui/${encodeURIComponent(slug)}`;
  return subPath ? `${base}/${subPath.replace(/^\/+/, '')}` : `${base}/`;
}

export const STACK_SDK_URL = '/api/stacks/v1/ks-stack-sdk.js';

// ---- Workdir file manager (Detail Files section + full-page file manager) --------

export async function listStackFiles(id: number, dir: string): Promise<StackFileEntry[]> {
  const res = await client.get<{ path: string; entries: StackFileEntry[] }>(
    `/api/stacks/${id}/files`,
    { params: { path: dir } },
  );
  return res.data.entries || [];
}

export async function readStackFile(id: number, filePath: string): Promise<StackFileContent> {
  const res = await client.get<StackFileContent>(`/api/stacks/${id}/files/read`, {
    params: { path: filePath },
  });
  return res.data;
}

export async function writeStackFile(id: number, filePath: string, content: string): Promise<void> {
  await client.post(`/api/stacks/${id}/files`, { op: 'write', path: filePath, content });
}

export async function mkdirStackPath(id: number, dirPath: string): Promise<void> {
  await client.post(`/api/stacks/${id}/files`, { op: 'mkdir', path: dirPath });
}

export async function renameStackPath(id: number, from: string, to: string): Promise<void> {
  await client.post(`/api/stacks/${id}/files`, { op: 'rename', path: from, new_path: to });
}

export async function deleteStackPath(id: number, target: string): Promise<void> {
  await client.post(`/api/stacks/${id}/files`, { op: 'delete', path: target });
}

export async function uploadStackFiles(id: number, dir: string, files: File[]): Promise<{ uploaded: number }> {
  const form = new FormData();
  for (const f of files) form.append('files', f, f.name);
  const res = await client.post<{ uploaded: number }>(
    `/api/stacks/${id}/files/upload`,
    form,
    { params: { path: dir }, headers: { 'Content-Type': 'multipart/form-data' } },
  );
  return res.data;
}

export async function downloadStackFile(id: number, filePath: string): Promise<Blob> {
  const res = await client.get<Blob>(`/api/stacks/${id}/files/download`, {
    params: { path: filePath },
    responseType: 'blob',
  });
  return res.data;
}
